#include <stdio.h>
int main(){int n,q,i,time=0,done,bt[20],r[20],wt[20]={0},tat[20];float aw=0,at=0;printf("Enter Number of Processes: ");scanf("%d",&n);for(i=0;i<n;i++){printf("Enter Burst Time for P%d: ",i+1);scanf("%d",&bt[i]);r[i]=bt[i];}printf("Enter Time Quantum: ");scanf("%d",&q);do{done=1;for(i=0;i<n;i++)if(r[i]>0){done=0;if(r[i]>q){time+=q;r[i]-=q;}else{time+=r[i];wt[i]=time-bt[i];r[i]=0;}}}while(!done);printf("\nProcess\tBT\tWT\tTAT\n");for(i=0;i<n;i++){tat[i]=bt[i]+wt[i];aw+=wt[i];at+=tat[i];printf("P%d\t%d\t%d\t%d\n",i+1,bt[i],wt[i],tat[i]);}printf("\nAverage Waiting Time = %.2f\nAverage Turnaround Time = %.2f\n",aw/n,at/n);return 0;}